function q(
  number: number,
  prompt: string,
  choices: [string, string, string, string],
  correct: string,
  explanation: string,
  source: keyof typeof refs,
): Question {
  const [title, path] = refs[source]
  return {
    id: `sc500-compute-${String(number).padStart(3, '0')}`,
    domainId: 'compute',
    prompt,
    choices: choices.map((text, index) => ({ id: String.fromCharCode(97 + index), text })),
    correctChoiceIds: [...correct],
    explanation,
    references: [{ title, url: `https://learn.microsoft.com/ja-jp/${path}` }],
  }
}

